input.command:
mkdir -p solutions && cd solutions
cat > t0-hello.woc <<'EOF'
leshdei "Hello, Utopia!";
EOF
cat > t0-count.woc <<'EOF'
weltuxle n := leidush(lono());
keit (weltuxle i := 1; i <= n; i := i + 1) {
    leshdei i;
}
EOF
cat > t0-factorial.woc <<'EOF'
weltuxle n := leidush(lono());
weltuxle f := 1;
keit (weltuxle i := 2; i <= n; i := i + 1) {
    f := f * i;
}
leshdei f;
EOF
cat > t0-fizzbuzz.woc <<'EOF'
weltuxle n := leidush(lono());
keit (weltuxle i := 1; i <= n; i := i + 1) {
    nei (i yeil 15 == 0) {
        leshdei "FizzBuzz";
    } wogeish nei (i yeil 3 == 0) {
        leshdei "Fizz";
    } wogeish nei (i yeil 5 == 0) {
        leshdei "Buzz";
    } wogeish {
        leshdei i;
    }
}
EOF
cat > t0-even-odd.woc <<'EOF'
weltuxle ev := 0;
weltuxle od := 0;
weltuxle line := lono();
krenul (line <> leitchux) {
    nei (leidush(line) yeil 2 == 0) {
        ev := ev + 1;
    } wogeish {
        od := od + 1;
    }
    line := lono();
}
leshdei "even " + ev;
leshdei "odd " + od;
EOF
cat > t0-day-names.woc <<'EOF'
weltuxle names := ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"];
weltuxle line := lono();
krenul (line <> leitchux) {
    weltuxle n := leidush(line);
    nei (n >= 1 elish n <= 7) {
        leshdei names[n - 1];
    } wogeish {
        leshdei "invalid";
    }
    line := lono();
}
EOF
cat > t0-reverse-lines.woc <<'EOF'
weltuxle xs := [];
weltuxle line := lono();
krenul (line <> leitchux) {
    koshkil(xs, line);
    line := lono();
}
keit (weltuxle i := dushzosh(xs) - 1; i >= 0; i := i - 1) {
    leshdei xs[i];
}
EOF
cd ..
W=bin/wochu
$W run solutions/t0-hello.woc
echo 5 | $W run solutions/t0-count.woc; echo 0 | $W run solutions/t0-count.woc
echo 20 | $W run solutions/t0-factorial.woc; echo 0 | $W run solutions/t0-factorial.woc
echo 15 | $W run solutions/t0-fizzbuzz.woc | tail -3
printf -- "-3\n4\n0\n-8\n7\n" | $W run solutions/t0-even-odd.woc
printf -- "1\n7\n0\n8\n-1\n3\n" | $W run solutions/t0-day-names.woc
printf "a\n\n  b c\nd\n" | $W run solutions/t0-reverse-lines.woc | cat -A
printf "" | $W run solutions/t0-reverse-lines.woc; printf "" | $W run solutions/t0-even-odd.woc

